26	type hooksDatabase struct {
27		datas.Database
28		db    *DoltDB
29		hooks []CommitHook
30		rsc   *ReplicationStatusController
31	}
32	
33	// CommitHook is an abstraction for executing arbitrary commands after atomic database commits
34	type CommitHook interface {
35		// Execute is arbitrary read-only function whose arguments are new Dataset commit into a specific Database.
36		// The returned values are a callback function and an error. The callback function is
37		// a Wait function which is optional. If returned, it will be registered with the ReplicationStatusController. If the
38		// hook implements NotifyWaitFailedCommitHook, it will be notified if the Wait function returns an error.
39		// The |Error| returned is actually ignored by the caller. It exists primarily for for unit testing. Any error which
40		// happens in a hook should be logged by the hook itself.
41		Execute(ctx context.Context, ds datas.Dataset, db *DoltDB) (func(context.Context) error, error)
42		// ExecuteForWorkingSets returns whether or not the hook should be executed for working set updates
43		ExecuteForWorkingSets() bool
44	}
45	
46	// NotifyWaitFailedCommitHook is an optional interface that can be implemented by CommitHooks.
47	// If a commit hook supports this interface, it can be notified if waiting for
48	// replication in the callback returned by |Execute| failed to complete in time
49	// or returned an error.
50	type NotifyWaitFailedCommitHook interface {
51		NotifyWaitFailed()
52	}
53	
54	func (db hooksDatabase) SetCommitHooks(ctx context.Context, postHooks []CommitHook) hooksDatabase {
55		db.hooks = make([]CommitHook, len(postHooks))
56		copy(db.hooks, postHooks)
57		return db
58	}
59	
60	func (db hooksDatabase) withReplicationStatusController(rsc *ReplicationStatusController) hooksDatabase {
61		db.rsc = rsc
62		return db
63	}
64	
65	func (db hooksDatabase) PostCommitHooks() []CommitHook {
66		toret := make([]CommitHook, len(db.hooks))
67		copy(toret, db.hooks)
68		return toret
69	}
70	
71	func (db hooksDatabase) ExecuteCommitHooks(ctx context.Context, ds datas.Dataset, onlyWS bool) {
72		var wg sync.WaitGroup
73		rsc := db.rsc
74		var ioff int
75		if rsc != nil {
76			ioff = len(rsc.Wait)
77			rsc.Wait = append(rsc.Wait, make([]func(context.Context) error, len(db.hooks))...)
78			rsc.NotifyWaitFailed = append(rsc.NotifyWaitFailed, make([]func(), len(db.hooks))...)
79		}
80		for il, hook := range db.hooks {
81			if !onlyWS || hook.ExecuteForWorkingSets() {
82				i := il
83				hook := hook
84				wg.Add(1)
85				go func() {
86					defer wg.Done()
87					// The error returned is intentionally ignored here. Hooks are expected to log errors themselves. The interface returns
88					// the error primarily for testing purposes.
89					f, _ := hook.Execute(ctx, ds, db.db)
90					if rsc != nil {
91						rsc.Wait[i+ioff] = f
92						if nf, ok := hook.(NotifyWaitFailedCommitHook); ok {
93							rsc.NotifyWaitFailed[i+ioff] = nf.NotifyWaitFailed
94						} else {
95							rsc.NotifyWaitFailed[i+ioff] = func() {}
96						}
97					}
98				}()
99			}
100		}
101		wg.Wait()
102		if rsc != nil {
103			j := ioff
104			for i := ioff; i < len(rsc.Wait); i++ {
105				// compact out any nil entries
106				if rsc.Wait[i] != nil {
107					rsc.Wait[j] = rsc.Wait[i]
108					rsc.NotifyWaitFailed[j] = rsc.NotifyWaitFailed[i]
109					j++
110				}
111			}
112			rsc.Wait = rsc.Wait[:j]
113			rsc.NotifyWaitFailed = rsc.NotifyWaitFailed[:j]
114		}
115	}
