117	func (db hooksDatabase) CommitWithWorkingSet(
118		ctx context.Context,
119		commitDS, workingSetDS datas.Dataset,
120		val types.Value, workingSetSpec datas.WorkingSetSpec,
121		prevWsHash hash.Hash, opts datas.CommitOptions,
122	) (datas.Dataset, datas.Dataset, error) {
123		commitDS, workingSetDS, err := db.Database.CommitWithWorkingSet(
124			ctx,
125			commitDS,
126			workingSetDS,
127			val,
128			workingSetSpec,
129			prevWsHash,
130			opts)
131		if err == nil {
132			db.ExecuteCommitHooks(ctx, commitDS, false)
133		}
134		return commitDS, workingSetDS, err
135	}
