238	func MakeServer(t *testing.T, dc driver.DoltCmdable, s *driver.Server, resources *DynamicResources, manualOps ...driver.SqlServerOpt) *driver.SqlServer {
239		if s == nil {
240			return nil
241		}
242		args := make([]string, len(s.Args))
243		for i := range args {
244			args[i] = resources.ApplyTemplate(s.Args[i])
245		}
246		opts := []driver.SqlServerOpt{
247			driver.WithArgs(args...),
248			driver.WithEnvs(append([]string{
249				"DOLT_CONTEXT_VALIDATION_ENABLED=true",
250				"DOLT_ENABLE_DYNAMIC_ASSERTS=true",
251			}, s.Envs...)...),
252			driver.WithName(s.Name),
253		}
254		if s.Port != 0 {
255			t.Fatal("cannot specify s.Port on these tests; please use {{get_port ...}} and dynamic_port: to specify a dynamic port.")
256		}
257		if s.DynamicPort == "" {
258			t.Fatal("you must specify s.DynamicPort on these tests; please use {{get_port ...}} and dynamic_port: to specify a dynamic port.")
259		}
260		port, ok := resources.GetPort(s.DynamicPort)
261		if !ok {
262			t.Fatalf("cannot find dynamic port %s after expanding server config, requested as dynamic server port", s.DynamicPort)
263		}
264		opts = append(opts, driver.WithPort(port))
265		opts = append(opts, manualOps...)
266	
267		var server *driver.SqlServer
268		var err error
269		if s.DebugPort != 0 {
270			server, err = driver.DebugSqlServer(dc, s.DebugPort, opts...)
271		} else {
272			server, err = driver.StartSqlServer(dc, opts...)
273		}
274	
275		require.NoError(t, err)
276		if len(s.ErrorMatches) > 0 {
277			err := server.ErrorStop()
278			require.Error(t, err)
279			output := server.Output.String()
280			for _, a := range s.ErrorMatches {
281				require.Regexp(t, a, output)
282			}
283			return nil
284		} else {
285			t.Cleanup(func() {
286				// We use assert, not require here, since FailNow() in
287				// a Cleanup does not make sense.
288				err := server.GracefulStop()
289				if assert.NoError(t, err) {
290					output := server.Output.String()
291					for _, a := range s.LogMatches {
